# -*- coding: utf-8 -*-
"""
Hand-reviewed findings table for the 100-app research set.

Each row is the OUTPUT of the pipeline after the verification passes described
in docs/architecture.md, not a hand-written guess. Provenance is explicit:

  verification:
    "grounded"  - a targeted web-research pass ran for this app in this session
                  and the evidence URLs below were returned by it.
    "catalog"   - Composio's published toolkit page supplied the structured auth
                  schemes / tool counts (data/composio_catalog.json).
    "prior"     - model prior anchored to the canonical documentation URL, NOT
                  independently re-fetched this run. Lowest trust tier; these
                  are the rows a reviewer should spot-check first.

  access taxonomy:
    SS    self-serve, free tier or free trial sufficient to get a working key
    SSP   self-serve, but a paid plan is required before credentials work
    REV   self-registration followed by an approval/review gate for production
    SALES contact sales / partnership / enterprise contract required
    NONE  no public API surface to build a toolkit against

Columns: id, auth_primary, auth_all, access, access_note, surface, mcp,
         buildable, blocker, evidence[], verification, confidence
"""

F = {}

def row(i, auth_primary, auth_all, access, access_note, surface, mcp,
        buildable, blocker, evidence, verification, confidence, one_liner):
    F[i] = dict(id=i, auth_primary=auth_primary, auth_all=auth_all, access=access,
                access_note=access_note, surface=surface, mcp=mcp,
                buildable=buildable, blocker=blocker, evidence=evidence,
                verification=verification, confidence=confidence, one_liner=one_liner)

